const first = $input.first().json;
const body = first.body ?? first;

const defaultScriptPath = 'C:\\CAMINHO\\DO\\PROJETO\\analisar_leads.py';
const defaultOutputDir = 'C:\\CAMINHO\\DO\\PROJETO\\saida';

const rawPaths = Array.isArray(body.csvPaths)
  ? body.csvPaths
  : Array.isArray(body.files)
    ? body.files
    : [body.csvPath ?? body.filePath].filter(Boolean);

if (!rawPaths.length) {
  throw new Error('Informe csvPath, filePath, csvPaths ou files no body do webhook.');
}

function isAbsoluteWindowsPath(value) {
  return /^[a-zA-Z]:[\\/]/.test(value) || /^\\\\[^\\/]+[\\/][^\\/]+/.test(value);
}

function cleanPath(value, name, options = {}) {
  const path = String(value ?? '').trim();
  if (!path) throw new Error(`${name} vazio.`);
  if (/["\r\n%!^&|<>]/.test(path)) throw new Error(`${name} contem caractere nao permitido para comando shell.`);
  if (!isAbsoluteWindowsPath(path)) throw new Error(`${name} deve ser um caminho absoluto do Windows.`);
  if (options.csv && !path.toLowerCase().endsWith('.csv')) throw new Error(`${name} deve terminar com .csv.`);
  return path;
}

function quote(value) {
  return `"${value}"`;
}

const scriptPath = cleanPath(body.scriptPath || defaultScriptPath, 'scriptPath');
const outputDir = cleanPath(body.outputDir || defaultOutputDir, 'outputDir');
const enrich = body.enrichWeb === false ? '' : ' --enrich-web';

return rawPaths.map((path) => {
  const csvPath = cleanPath(path, 'csvPath', { csv: true });
  const command = `python ${quote(scriptPath)} --input ${quote(csvPath)} --output-dir ${quote(outputDir)}${enrich}`;
  return { json: { csvPath, outputDir, scriptPath, command } };
});

const results = $input.all().map((item) => {
  const raw = String(item.json.stdout ?? '').trim();
  let parsed = {};
  let parseError = null;

  if (raw) {
    try {
      parsed = JSON.parse(raw);
    } catch (error) {
      parseError = error.message;
    }
  }

  const exitCode = Number(item.json.exitCode ?? (item.json.error ? 1 : 0));
  const outputs = parsed.outputs ?? {};
  const outputPaths = [
    outputs.all_csv,
    outputs.html_report,
    outputs.manifest,
    ...Object.values(outputs.groups ?? {})
  ].filter(Boolean);

  return {
    ok: exitCode === 0 && !parseError && parsed.ok !== false,
    exitCode,
    inputPath: parsed.source_file ?? null,
    totalLeads: parsed.total_leads ?? 0,
    summary: parsed.summary ?? null,
    outputPaths,
    stderr: item.json.stderr ?? null,
    error: parseError ?? item.json.error?.message ?? item.json.error ?? parsed.error ?? null
  };
});

return [{
  json: {
    ok: results.every((result) => result.ok),
    count: results.length,
    results
  }
}];
